using System.IO;
using System.Security.Cryptography;using System.Text;using System.Text.Json;
namespace OpenIsland.App.Services;
public sealed class ProviderSettingsService{readonly string path;public ProviderSettingsService(){var d=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"OpenIsland");Directory.CreateDirectory(d);path=Path.Combine(d,"provider.json");}public ProviderSettings Load(){try{var x=JsonSerializer.Deserialize<S>(File.ReadAllText(path));return x is null?ProviderSettings.Default:new(x.Url??ProviderSettings.Default.BaseUrl,x.Model??ProviderSettings.Default.Model,string.IsNullOrEmpty(x.Key)?"":Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(x.Key),null,DataProtectionScope.CurrentUser)));}catch{return ProviderSettings.Default;}}public void Save(ProviderSettings x){var k=string.IsNullOrWhiteSpace(x.ApiKey)?"":Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(x.ApiKey),null,DataProtectionScope.CurrentUser));File.WriteAllText(path,JsonSerializer.Serialize(new S(x.BaseUrl,x.Model,k)));}sealed record S(string? Url,string? Model,string? Key);}